// Track space key state globally so the sensor can access it
// This is necessary because the PointerSensor activator doesn't have access to React state
let isSpacePressed = false

// Custom PointerSensor that doesn't activate when Space is pressed
// This allows Space+drag to pan the canvas without also dragging elements
class PanAwarePointerSensor extends PointerSensor {
  static activators = [
    {
      eventName: 'onPointerDown' as const,
      handler: ({ nativeEvent: event }: { nativeEvent: PointerEvent }) => {
        // Don't start drag when Space is pressed (panning mode)
        if (isSpacePressed) {
          return false
        }

        // Default PointerSensor behavior: only respond to primary button
        if (event.button !== 0 || event.isPrimary === false) {
          return false
        }

        return true
      },
    },
  ]
}

export interface ComponentIndex {
  [componentName: string]: {
    path: string
    exportName: string
    props?: Record<string, any>
  }
}

export interface LunagraphEditorProps {
  /**
   * Map of component names to actual component functions
   * Example: import * as UI from '@/components/ui'
   * Then pass: components={UI}
   */
  components: Record<string, React.ComponentType<any>>

  /**
   * Component index generated by lunagraph scan
   * Example: import componentIndex from '@/.lunagraph/ComponentIndex.json'
   * Then pass: componentIndex={componentIndex}
   */
  componentIndex: ComponentIndex

  /**
   * Map of snapshot component names to snapshot components
   * Generated by dev-server when editing components
   * Example: import { snapshots } from './.lunagraph/snapshots'
   * Then pass: snapshots={snapshots}
   */
  snapshots?: Record<string, React.ComponentType<any>>

  /**
   * Map of icon library package names to their configurations
   * Example:
   * import * as PhosphorIcons from "@phosphor-icons/react"
   * iconLibraries={{
   *   "@phosphor-icons/react": {
   *     icons: PhosphorIcons,
   *     displayName: "Phosphor",
   *     defaultProps: { size: 16, weight: "regular" }
   *   }
   * }}
   */
  iconLibraries?: Record<string, IconLibraryConfig>

  /**
   * Read-only mode - disables editing, drag/drop, and dev-server connections.
   * Use this for deployed/production views where users can only view the canvas.
   */
  readOnly?: boolean

  /**
   * Initial elements to display on the canvas (single page).
   * Use this with readOnly mode to load static canvas data.
   * Example: import canvasData from './.lunagraph/canvases/canvas-1/canvas.json'
   * Then pass: initialElements={canvasData.elements}
   * 
   * For multiple pages, use initialPages instead.
   */
  initialElements?: FEElement[]

  /**
   * Initial pages for multi-page read-only mode.
   * Each page contains its own elements array.
   * Example:
   * import page1 from './.lunagraph/canvases/page-1/canvas.json'
   * import page2 from './.lunagraph/canvases/page-2/canvas.json'
   * initialPages={[
   *   { id: 'page-1', name: 'Homepage', elements: page1.elements },
   *   { id: 'page-2', name: 'About', elements: page2.elements }
   * ]}
   */
  initialPages?: Array<{
    id: string
    name: string
    elements: FEElement[]
  }>

  /**
   * Initial zoom level (default: 1)
   */
  initialZoom?: number

  /**
   * Initial pan position (default: { x: 0, y: 0 })
   */
  initialPan?: { x: number; y: number }

  /**
   * Dev server URL for file operations, snapshots, and drafts.
   * Default: 'http://localhost:4001' or NEXT_PUBLIC_LUNAGRAPH_DEV_SERVER env var
   */
  devServerUrl?: string

  /**
   * Pre-generated snapshot metadata for production read-only mode.
   * Generated by `lunagraph generate-snapshots` command.
   * Example: import snapshotMetadata from './.lunagraph/snapshots/metadata.json'
   * Then pass: snapshotMetadata={snapshotMetadata}
   */
  snapshotMetadata?: Record<string, {
    componentName: string
    snapshotComponentName: string
    filePath: string
    snapshotPath: string
    snapshotProps: Array<{
      name: string
      source: string  // 'originalProp' | 'useState' | 'useContext' | 'customHook' | 'internalConstant'
      initialValue?: any
      type?: string
      options?: string[]
      hasImportDefault?: boolean
    }>
    initialMockValues: Record<string, any>
    sourceCode?: string  // Pre-loaded source code for read-only mode
    internalComponents?: Array<{
      name: string
      startLine: number
      endLine: number
    }>
  }>
}

// Inner component that uses the DevServerContext
const LunagraphEditorInner = ({
  components,
  componentIndex,
  snapshots: snapshotsProp = {},
  iconLibraries = {},
  readOnly = false,
  initialElements,
  initialPages,
  initialZoom = 1,
  initialPan = { x: 0, y: 0 },
  snapshotMetadata = {},
}: Omit<LunagraphEditorProps, 'devServerUrl'>) => {
  const devServerUrl = useDevServerUrl()
  const router = useRouterCompat()
  const searchParams = useSearchParamsCompat()
  const editingFile = searchParams?.get('file') ?? null
  const elementParam = searchParams?.get('element') ?? null
  const pageParam = searchParams?.get('page') ?? null

  // Keep snapshots in state so we can update when new ones are created
  const snapshots = snapshotsProp

  const [selectedElementIds, setSelectedElementIds] = useState<Set<string>>(new Set())
  const [pendingElementToCenter, setPendingElementToCenter] = useState<string | null>(null)
  const [chatMessages, setChatMessages] = useState<ChatMessageItem[]>([])

  // Track if we've handled the share link (moved after handleSelectPage is defined)
  const hasHandledShareLinkRef = useRef(false)

  // Helper to get first selected ID (for single-element operations)
  const selectedElementId = selectedElementIds.size === 1 ? Array.from(selectedElementIds)[0] : null

  // Handler for element selection with Shift+Click support for multi-select
  // When selecting, removes any ancestors or descendants to prevent nested selection confusion
  const handleSelectElement = useCallback((id: string | null, addToSelection: boolean = false) => {
    if (id === null) {
      // Clicking empty space clears selection
      setSelectedElementIds(new Set())
      return
    }

    if (addToSelection) {
      // Shift+Click: toggle element in selection, but handle parent/child conflicts
      setSelectedElementIds(prev => {
        const next = new Set(prev)

        if (next.has(id)) {
          // Already selected - deselect it
          next.delete(id)
        } else {
          // Adding to selection - remove any ancestors or descendants
          // Use cache for O(1) lookups instead of O(n) tree traversals
          const cache = elementCacheRef.current

          // Helper: check if childId is a descendant of parentId using parent chain (O(depth))
          const isDescendantOf = (childId: string, parentId: string): boolean => {
            let currentId: string | null = childId
            while (currentId) {
              const parent = cache.parentById.get(currentId)
              if (parent === parentId) return true
              currentId = parent ?? null
            }
            return false
          }

          // Check each currently selected element
          for (const selectedId of Array.from(next)) {
            // Is the new element a descendant of an already-selected element?
            if (isDescendantOf(id, selectedId)) {
              // New element is child of selected - remove parent
              next.delete(selectedId)
            }

            // Is an already-selected element a descendant of the new element?
            if (isDescendantOf(selectedId, id)) {
              // Selected element is child of new - remove child
              next.delete(selectedId)
            }
          }

          next.add(id)
        }

        // If result is empty (toggled off the only selection), still select the clicked element
        // This handles the case: nothing selected -> shift+click -> should select
        if (next.size === 0) {
          next.add(id)
        }

        return next
      })
    } else {
      // Regular click: single select
      setSelectedElementIds(new Set([id]))
    }
  }, [])

  const [hoverElementId, setHoverElementId] = useState<string | null>(null)
  const [editingTextId, setEditingTextId] = useState<string | null>(null)
  const [editingTextBounds, setEditingTextBounds] = useState<{ width: number; height: number } | null>(null)
  const [canvasZoom, setCanvasZoom] = useState(1)
  const [cmdPressed, setCmdPressed] = useState(false)
  const [showCreateComponentModal, setShowCreateComponentModal] = useState(false)

  // Track mouse position for re-hover on Cmd toggle
  const lastMousePosRef = useRef<{ x: number; y: number } | null>(null)

  // Track canvas transform and refs for paste/add position calculation
  const canvasRef = useRef<HTMLDivElement>(null)
  const viewportRef = useRef<HTMLDivElement>(null)
  const chatPanelRef = useRef<ChatPanelHandle>(null)
  const canvasTransformRef = useRef({ scale: 1, positionX: 0, positionY: 0 })
  const mousePositionRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 })
  const hasLoadedTransformRef = useRef(false) // Track if we've loaded from localStorage

  // Load initial transform from localStorage (skip if element param present - we'll center on that)
  const [initialCanvasTransform, setInitialCanvasTransform] = useState<{ scale: number; positionX: number; positionY: number } | undefined>(undefined)
  const [transformKey, setTransformKey] = useState(0) // Key to force re-mount TransformWrapper

  useEffect(() => {
    // Don't load from localStorage if we have an element to center on
    if (elementParam) {
      hasLoadedTransformRef.current = true
      return
    }

    // Only load saved transform for canvas tabs, not file tabs
    const currentTab = tabs.find(t => t.id === activeTabId)
    if (currentTab?.type !== 'canvas') {
      hasLoadedTransformRef.current = true
      return
    }

    const saved = localStorage.getItem('lunagraph-canvas-transform')
    if (saved) {
      try {
        const parsed = JSON.parse(saved)
        setInitialCanvasTransform(parsed)
        canvasTransformRef.current = parsed
        // Also save to the canvas tab so it persists when switching tabs
        setTabs(prev => prev.map(t =>
          t.id === 'canvas-1' ? { ...t, transform: parsed } : t
        ))
        // Increment key to force Canvas re-mount with new initial values
        setTransformKey(k => k + 1)
        // Clear initialCanvasTransform after a tick so tab switching uses tab.transform
        setTimeout(() => setInitialCanvasTransform(undefined), 100)
      } catch (e) {
        console.error('[Lunagraph] Failed to parse transform:', e)
      }
    }
    // Mark as loaded so onTransformChange can start saving
    hasLoadedTransformRef.current = true
  }, []) // Only run once on mount

  // Track Cmd/Ctrl key for deep selection
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey) {
        setCmdPressed(true)
      }
    }
    const handleKeyUp = (e: KeyboardEvent) => {
      if (!e.metaKey && !e.ctrlKey) {
        setCmdPressed(false)
      }
    }
    const handleMouseMove = (e: MouseEvent) => {
      lastMousePosRef.current = { x: e.clientX, y: e.clientY }
      mousePositionRef.current = { x: e.clientX, y: e.clientY }
      // Sync cmdPressed with actual key state (in case we missed keyup while outside window)
      const shouldBePressed = e.metaKey || e.ctrlKey
      setCmdPressed(prev => prev !== shouldBePressed ? shouldBePressed : prev)
    }
    window.addEventListener('keydown', handleKeyDown)
    window.addEventListener('keyup', handleKeyUp)
    window.addEventListener('mousemove', handleMouseMove)
    // Handle blur (when user switches windows while holding Cmd)
    const handleBlur = () => setCmdPressed(false)
    window.addEventListener('blur', handleBlur)
    return () => {
      window.removeEventListener('keydown', handleKeyDown)
      window.removeEventListener('keyup', handleKeyUp)
      window.removeEventListener('mousemove', handleMouseMove)
      window.removeEventListener('blur', handleBlur)
    }
  }, [])

  // Track Space key for panning mode - syncs with global isSpacePressed for the sensor
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space') {
        const target = e.target as HTMLElement
        if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) {
          return
        }
        isSpacePressed = true
      }
    }
    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space') {
        isSpacePressed = false
      }
    }
    const handleBlur = () => {
      isSpacePressed = false
    }
    window.addEventListener('keydown', handleKeyDown)
    window.addEventListener('keyup', handleKeyUp)
    window.addEventListener('blur', handleBlur)
    return () => {
      window.removeEventListener('keydown', handleKeyDown)
      window.removeEventListener('keyup', handleKeyUp)
      window.removeEventListener('blur', handleBlur)
    }
  }, [])

  // Re-trigger hover when cmdPressed changes to recalculate with new selection mode
  useEffect(() => {
    if (lastMousePosRef.current) {
      const { x, y } = lastMousePosRef.current
      // Dispatch a synthetic mouseover event at the current mouse position
      const elementUnderMouse = document.elementFromPoint(x, y)
      if (elementUnderMouse) {
        const event = new MouseEvent('mouseover', {
          bubbles: true,
          cancelable: true,
          clientX: x,
          clientY: y,
        })
        elementUnderMouse.dispatchEvent(event)
      }
    }
  }, [cmdPressed])

  // Focus on element in canvas (centers the view on the element)
  const handleFocusElement = useCallback((elementId: string) => {
    setPendingElementToCenter(elementId)
  }, [])

  // Pages state - list of all canvas pages (like Figma pages)
  // Initialize from initialPages if provided (for read-only multi-page mode)
  const [pages, setPages] = useState<PageInfo[]>(() => {
    if (initialPages && initialPages.length > 0) {
      return initialPages.map(p => ({
        id: p.id,
        name: p.name,
        elementCount: p.elements.length
      }))
    }
    return [{ id: 'canvas-1', name: 'Page 1' }]
  })
  const [activePageId, setActivePageId] = useState(() => {
    if (initialPages && initialPages.length > 0) {
      return initialPages[0].id
    }
    return 'canvas-1'
  })

  // Store all pages' elements for read-only mode (so we can switch without server)
  const [pagesData, setPagesData] = useState<Map<string, FEElement[]>>(() => {
    if (initialPages && initialPages.length > 0) {
      const map = new Map<string, FEElement[]>()
      for (const p of initialPages) {
        map.set(p.id, p.elements)
      }
      return map
    }
    return new Map()
  })

  // Tabs state - starts with the active page's canvas, use initialElements if provided
  const [tabs, setTabs] = useState<EditorTab[]>(() => {
    const firstPage = initialPages?.[0]
    return [{
      id: firstPage?.id || 'canvas-1',
      name: firstPage?.name || 'Page 1',
      type: 'canvas' as const,
      canvasId: firstPage?.id || 'canvas-1',
      canvasPath: `.lunagraph/canvases/${firstPage?.id || 'canvas-1'}/`,
      elements: firstPage?.elements || initialElements || []
    }]
  })
  const [activeTabId, setActiveTabId] = useState(() => {
    return initialPages?.[0]?.id || 'canvas-1'
  })

  // Share link handler - includes page ID so the link opens the right canvas
  const handleShareLink = useCallback(() => {
    if (!selectedElementId) return
    const url = new URL(window.location.href)
    url.searchParams.set('element', selectedElementId)
    // Include page ID for multi-page support
    if (activePageId) {
      url.searchParams.set('page', activePageId)
    }
    navigator.clipboard.writeText(url.toString())
    toast("Share link is copied.")
  }, [selectedElementId, activePageId])

  // Only use dev-server hooks when not in readOnly mode
  const { loadFile, createSnapshot, loadDraft, saveDraft, deleteDraft, listDrafts, isLoading } = useDevServer()
  const { saveCanvas, loadCanvas, listCanvases, createComponent, createComponentFromFile } = useCanvasPersistence()

  // Track all drafts from disk (for AssetsPanel badges)
  const [draftComponentNames, setDraftComponentNames] = useState<Set<string>>(new Set())

  // History management for undo/redo (per-tab)
  const history = useTabHistory({ maxHistory: 50 })

  // Track last saved state to avoid unnecessary saves
  const lastSavedStateRef = useRef<string>('')

  // Draft conflict dialog state
  const [draftConflict, setDraftConflict] = useState<{
    isOpen: boolean
    componentName: string
    filePath: string
    draftElements: FEElement[]
    draftMockValues: Record<string, any>
    pendingTab: EditorTab | null
  } | null>(null)

  // Load all pages on mount (skip if readOnly or initialElements/initialPages provided)
  useEffect(() => {
    // Skip loading from dev-server if readOnly or initial data already provided
    if (readOnly || initialElements || initialPages) return

    const loadAllPages = async () => {
      // First, list all existing canvases (pages)
      const listResult = await listCanvases()

      if (listResult.success && listResult.canvases && listResult.canvases.length > 0) {
        // Sort by name for consistent ordering
        const sortedCanvases = [...listResult.canvases].sort((a, b) =>
          (a.name || a.id).localeCompare(b.name || b.id)
        )

        // Update pages list
        setPages(sortedCanvases.map(c => ({
          id: c.id,
          name: c.name || c.id,
          elementCount: c.elements?.length || 0
        })))

        // Load the first page's canvas
        const firstPageId = sortedCanvases[0].id
        const firstCanvas = sortedCanvases[0]

        setActivePageId(firstPageId)
        setTabs(prev => prev.map(tab =>
          tab.type === 'canvas'
            ? {
              ...tab,
              id: firstPageId,
              name: firstCanvas.name || firstPageId,
              canvasId: firstPageId,
              canvasPath: `.lunagraph/canvases/${firstPageId}/`,
              elements: firstCanvas.elements || [],
              canvasSaved: true,
            }
            : tab
        ))
        setActiveTabId(firstPageId)

        // Update last saved state to prevent immediate re-save
        lastSavedStateRef.current = JSON.stringify({
          elements: firstCanvas.elements || [],
          zoom: 1,
        })
      } else {
        // No existing canvases, create the default canvas-1
        const result = await loadCanvas('canvas-1')
        if (result.success && result.canvas) {
          setTabs(prev => prev.map(tab =>
            tab.id === 'canvas-1'
              ? {
                ...tab,
                elements: result.canvas!.elements,
                canvasSaved: true,
              }
              : tab
          ))
          // Update last saved state to prevent immediate re-save
          lastSavedStateRef.current = JSON.stringify({
            elements: result.canvas.elements,
            zoom: 1,
          })
        }
      }
    }
    loadAllPages()
  }, [readOnly, initialElements, initialPages]) // Only run on mount

  // Page switching handler - loads a different canvas
  const handleSelectPage = useCallback(async (pageId: string) => {
    if (pageId === activePageId) return

    const pageName = pages.find(p => p.id === pageId)?.name || pageId
    let newElements: FEElement[] = []

    if (readOnly) {
      // In read-only mode, use cached pagesData (no server calls)
      newElements = pagesData.get(pageId) || []
    } else {
      // Save current canvas state before switching (it will auto-save, but let's be explicit)
      const currentCanvasTab = tabs.find(t => t.type === 'canvas' && t.canvasId === activePageId)
      if (currentCanvasTab) {
        await saveCanvas({
          id: activePageId,
          name: currentCanvasTab.name,
          elements: currentCanvasTab.elements,
        })
      }

      // Load the new page's canvas from server
      const result = await loadCanvas(pageId)
      newElements = result.success && result.canvas ? result.canvas.elements : []
    }

    // Update the canvas tab with the new page's data
    setTabs(prev => prev.map(tab =>
      tab.type === 'canvas'
        ? {
          ...tab,
          id: pageId,
          name: pageName,
          canvasId: pageId,
          canvasPath: `.lunagraph/canvases/${pageId}/`,
          elements: newElements,
          canvasSaved: true,
          transform: undefined, // Reset transform when switching pages
        }
        : tab
    ))

    setActivePageId(pageId)
    setActiveTabId(pageId)

    // Update last saved state
    lastSavedStateRef.current = JSON.stringify({
      elements: newElements,
      zoom: 1,
    })

    // Clear selection when switching pages
    setSelectedElementIds(new Set())
  }, [activePageId, tabs, pages, readOnly, pagesData, saveCanvas, loadCanvas])

  // Create new page handler
  const handleCreatePage = useCallback(async () => {
    // Generate a unique page ID
    const existingIds = pages.map(p => p.id)
    let newId = 'page-1'
    let counter = 1
    while (existingIds.includes(newId)) {
      counter++
      newId = `page-${counter}`
    }

    // Generate page name
    const newName = `Page ${pages.length + 1}`

    // Create the page
    const newPage: PageInfo = {
      id: newId,
      name: newName,
      elementCount: 0
    }

    // Add to pages list
    setPages(prev => [...prev, newPage])

    // Save the empty canvas to disk
    await saveCanvas({
      id: newId,
      name: newName,
      elements: [],
    })

    // Switch to the new page
    handleSelectPage(newId)
  }, [pages, saveCanvas, handleSelectPage])

  // Rename page handler
  const handleRenamePage = useCallback(async (pageId: string, newName: string) => {
    // Update pages list
    setPages(prev => prev.map(p =>
      p.id === pageId ? { ...p, name: newName } : p
    ))

    // Update tab if this is the active page
    setTabs(prev => prev.map(tab =>
      tab.type === 'canvas' && tab.canvasId === pageId
        ? { ...tab, name: newName }
        : tab
    ))

    // Save the canvas with the new name
    const canvasTab = tabs.find(t => t.type === 'canvas' && t.canvasId === pageId)
    if (canvasTab) {
      await saveCanvas({
        id: pageId,
        name: newName,
        elements: canvasTab.elements,
      })
    }
  }, [tabs, saveCanvas])

  // Delete page handler
  const handleDeletePage = useCallback(async (pageId: string) => {
    if (pages.length <= 1) return // Don't delete the last page

    // Remove from pages list
    const newPages = pages.filter(p => p.id !== pageId)
    setPages(newPages)

    // If deleting the active page, switch to another page
    if (pageId === activePageId) {
      const nextPage = newPages[0]
      if (nextPage) {
        handleSelectPage(nextPage.id)
      }
    }

    // TODO: Optionally delete the canvas file from disk
    // For now, just remove from UI - the file will remain on disk
  }, [pages, activePageId, handleSelectPage])

  // Handle share link with page and element params
  // Switch to the correct page first, then center on the element
  useEffect(() => {
    if (hasHandledShareLinkRef.current) return
    if (!elementParam) return

    // If a page is specified and it's different from current, switch to it
    if (pageParam && pageParam !== activePageId) {
      // Check if the page exists
      const pageExists = pages.some(p => p.id === pageParam)
      if (pageExists) {
        hasHandledShareLinkRef.current = true
        // Switch to the page, then the element will be centered after page loads
        handleSelectPage(pageParam).then(() => {
          setPendingElementToCenter(elementParam)
        })
        return
      }
    }

    // No page switch needed, just center on the element
    hasHandledShareLinkRef.current = true
    setPendingElementToCenter(elementParam)
  }, [elementParam, pageParam, activePageId, pages, handleSelectPage])

  // Load all drafts on mount (for AssetsPanel badges)
  const refreshDraftList = useCallback(async () => {
    if (readOnly) return
    const result = await listDrafts()
    if (result.success) {
      setDraftComponentNames(new Set(result.drafts.map(d => d.componentName)))
    }
  }, [readOnly, listDrafts])

  useEffect(() => {
    refreshDraftList()
  }, []) // Only on mount

  // Track if we've restored tabs to prevent saving during restore
  const hasRestoredTabsRef = useRef(false)

  // Save open file tabs to localStorage when tabs change
  useEffect(() => {
    // Don't save during initial restore or in readOnly mode
    if (!hasRestoredTabsRef.current || readOnly) return

    const fileTabs = tabs
      .filter(tab => tab.type === 'file' && tab.filePath)
      .map(tab => ({
        componentName: tab.name,
        filePath: tab.filePath!,
      }))

    localStorage.setItem('lunagraph-open-tabs', JSON.stringify(fileTabs))
    localStorage.setItem('lunagraph-active-tab', activeTabId)
  }, [tabs, activeTabId, readOnly])

  // Restore saved tabs on mount
  useEffect(() => {
    if (readOnly) {
      hasRestoredTabsRef.current = true
      return
    }

    const restoreTabs = async () => {
      const savedTabs = localStorage.getItem('lunagraph-open-tabs')
      const savedActiveTab = localStorage.getItem('lunagraph-active-tab')

      if (savedTabs) {
        try {
          const fileTabs = JSON.parse(savedTabs) as Array<{ componentName: string; filePath: string }>

          // Open each saved tab sequentially
          for (const tab of fileTabs) {
            // Use the same logic as onEditComponent but inline to avoid dependency issues
            const existingTab = tabs.find(t => t.filePath === tab.filePath)
            if (!existingTab) {
              // Create snapshot and open tab
              const draftResult = await loadDraft(tab.componentName)
              const result = await createSnapshot(tab.filePath, tab.componentName)

              if (result.success) {
                const allSnapshotProps = result.snapshotProps || []
                const variables = allSnapshotProps.map(p => p.name)
                const props = allSnapshotProps.filter(p => p.source === 'originalProp').map(p => p.name)
                const initialValues: Record<string, any> = {}
                for (const prop of allSnapshotProps) {
                  if (prop.initialValue !== undefined) {
                    initialValues[prop.name] = prop.initialValue
                  }
                }

                const newTab: EditorTab = {
                  id: generatePrefixedId('file'),
                  name: tab.componentName,
                  type: 'file',
                  filePath: tab.filePath,
                  elements: [],
                  snapshotComponentName: result.snapshotComponentName,
                  snapshotProps: result.snapshotProps,
                  mockValues: result.initialMockValues || {},
                  variables,
                  props,
                  initialValues,
                  internalComponents: result.internalComponents,
                }

                // Load from draft if available
                if (draftResult.success && draftResult.draft && !draftResult.sourceModifiedSinceDraft) {
                  newTab.elements = draftResult.draft.elements
                  newTab.mockValues = draftResult.draft.mockValues
                  newTab.hasUnsavedChanges = true
                  newTab.lastSavedElements = ''
                  newTab.loadedFromDraft = true
                  initializedTabsRef.current.add(newTab.id)
                }

                setTabs(prev => [...prev, newTab])
              }
            }
          }

          // Restore active tab if it was a file tab and exists
          if (savedActiveTab && savedActiveTab !== 'canvas-1') {
            // Wait a tick for tabs to be added, then try to activate
            setTimeout(() => {
              setTabs(currentTabs => {
                const targetTab = currentTabs.find(t =>
                  t.type === 'file' &&
                  fileTabs.some(ft => ft.filePath === t.filePath)
                )
                if (targetTab) {
                  setActiveTabId(targetTab.id)
                }
                return currentTabs
              })
            }, 100)
          }
        } catch (e) {
          console.error('[Lunagraph] Failed to restore tabs:', e)
        }
      }

      hasRestoredTabsRef.current = true
    }

    restoreTabs()
  }, []) // Only on mount

  // Handle element URL param - select element and center on it
  useEffect(() => {
    if (!pendingElementToCenter) return

    // Wait for next frame to ensure layout is ready
    const timeoutId = setTimeout(() => {
      requestAnimationFrame(() => {
        // Select the element
        setSelectedElementIds(new Set([pendingElementToCenter]))

        // Find the element to get its canvasPosition
        const currentElements = tabs.find(t => t.id === activeTabId)?.elements || []

        // Find element and its root parent with canvasPosition
        const findElementWithPosition = (elements: FEElement[], targetId: string, rootCanvasPos?: { x: number; y: number }): { element: FEElement; canvasPos: { x: number; y: number } } | null => {
          for (const el of elements) {
            const currentCanvasPos = el.canvasPosition || rootCanvasPos
            if (el.id === targetId && currentCanvasPos) {
              return { element: el, canvasPos: currentCanvasPos }
            }
            if ('children' in el && el.children) {
              const found = findElementWithPosition(el.children, targetId, currentCanvasPos)
              if (found) return found
            }
          }
          return null
        }

        const result = findElementWithPosition(currentElements, pendingElementToCenter)

        if (result) {
          const { element, canvasPos } = result

          // Get viewport dimensions - use window minus UI panels as fallback
          // Left panel ~240px, right panel ~280px, top ~80px, bottom ~40px
          const viewportRect = viewportRef.current?.getBoundingClientRect()
          const viewportWidth = viewportRect?.width || (window.innerWidth - 520)
          let viewportHeight = viewportRect?.height || (window.innerHeight - 120)

          // Sanity check - if viewport height is unreasonable (canvas size), use window fallback
          if (viewportHeight > 1500) {
            viewportHeight = window.innerHeight - 120
          }

          // Get element size from styles if available
          const stylesWidth = (element as any).styles?.width
          const stylesHeight = (element as any).styles?.height
          const elementWidth = typeof stylesWidth === 'number' ? stylesWidth : 200
          const elementHeight = typeof stylesHeight === 'number' ? stylesHeight : 200

          // Calculate transform to center the element at scale 1
          // posX = viewportWidth/2 - canvasPos.x - elementWidth/2
          const scale = 1
          const newTransform = {
            scale,
            positionX: viewportWidth / 2 - canvasPos.x - elementWidth / 2,
            positionY: viewportHeight / 2 - canvasPos.y - elementHeight / 2,
          }

          setInitialCanvasTransform(newTransform)
          canvasTransformRef.current = newTransform
          setTransformKey(k => k + 1)
          // Clear initialCanvasTransform after a tick so tab switching uses tab.transform
          setTimeout(() => setInitialCanvasTransform(undefined), 100)
        }

        setPendingElementToCenter(null)
      })
    }, 100)

    return () => clearTimeout(timeoutId)
  }, [pendingElementToCenter, tabs, activeTabId])

  // Reset transform when switching to a file tab (component editing)
  // Only run when activeTabId changes, not when tabs change (that would reset on every pan!)
  const prevActiveTabIdRef = useRef(activeTabId)
  useEffect(() => {
    if (prevActiveTabIdRef.current === activeTabId) return // Only run on tab switch
    prevActiveTabIdRef.current = activeTabId

    const currentTab = tabs.find(t => t.id === activeTabId)
    if (currentTab?.type === 'file' && !currentTab.transform) {
      // File tabs start at default position if no saved transform
      canvasTransformRef.current = { scale: 1, positionX: 0, positionY: 0 }
    }
  }, [activeTabId, tabs])

  // Get active tab
  const activeTab = tabs.find(t => t.id === activeTabId)

  // Create a merged componentIndex that includes internal component props when editing a file
  const mergedComponentIndex = useMemo(() => {
    if (!activeTab?.internalComponents?.length) return componentIndex

    // Merge internal component props into the componentIndex
    const merged = { ...componentIndex }
    for (const ic of activeTab.internalComponents) {
      if (ic.props) {
        merged[ic.name] = {
          path: activeTab.filePath || '',
          exportName: ic.name,
          props: ic.props,
        }
      }
    }
    return merged
  }, [componentIndex, activeTab?.internalComponents, activeTab?.filePath])

  // Current elements = active tab's elements
  const elements = activeTab?.elements || []

  // Build element cache for O(1) lookups - used for multi-select parent/child detection
  const elementCache = useMemo(() => buildElementCache(elements), [elements])

  const elementsRef = useRef(elements)
  const elementCacheRef = useRef(elementCache)

  useEffect(() => {
    elementsRef.current = elements
    elementCacheRef.current = elementCache
  }, [elements, elementCache])

  // Update active tab's elements (supports both direct value and updater function)
  // Also tracks unsaved changes for file tabs by comparing to lastSavedElements
  const setElements = useCallback((newElements: FEElement[] | ((prev: FEElement[]) => FEElement[])) => {
    setTabs(prev => prev.map(tab => {
      if (tab.id !== activeTabId) return tab

      const updatedElements = typeof newElements === 'function'
        ? newElements(tab.elements)
        : newElements

      // Track unsaved changes for file tabs
      if (tab.type === 'file' && tab.lastSavedElements) {
        const currentElementsKey = JSON.stringify(updatedElements)
        const hasUnsavedChanges = currentElementsKey !== tab.lastSavedElements
        return { ...tab, elements: updatedElements, hasUnsavedChanges }
      }

      return { ...tab, elements: updatedElements }
    }))
  }, [activeTabId])

  // Render snapshot component
  const { elements: snapshotElements, rendererElement: snapshotRendererElement } = useSnapshotRenderer({
    snapshotComponentName: activeTab?.snapshotComponentName,
    mockValues: activeTab?.mockValues || {},
    snapshots,
    components,
    iconLibraries,
    key: `${activeTab?.snapshotVersion || 0}-${JSON.stringify(activeTab?.mockValues)}`,
  })

  // Update tab elements when snapshot renders
  const lastSnapshotRef = useRef<string>('')
  const initializedTabsRef = useRef<Set<string>>(new Set())

  useEffect(() => {
    const hasSnapshot = activeTab?.type === 'file' && activeTab.snapshotComponentName && snapshotElements.length > 0
    if (!hasSnapshot || !activeTabId) return

    // Only update if elements actually changed (prevent infinite loop)
    const elementsKey = JSON.stringify(snapshotElements)
    if (elementsKey === lastSnapshotRef.current) {
      return
    }
    lastSnapshotRef.current = elementsKey

    // Check if this tab has been initialized before
    const isFirstRender = !initializedTabsRef.current.has(activeTabId)

    if (isFirstRender) {
      // First render: use snapshot elements directly and mark as clean (no unsaved changes)
      initializedTabsRef.current.add(activeTabId)
      setTabs(prev => prev.map(tab =>
        tab.id === activeTabId ? {
          ...tab,
          elements: snapshotElements,
          lastSavedElements: elementsKey,
          hasUnsavedChanges: false,
        } : tab
      ))
    } else {
      // Skip merge if tab was loaded from draft - keep draft elements intact
      if (activeTab?.loadedFromDraft) {
        // Clear the flag now that we've skipped the first merge
        setTabs(prev => prev.map(tab =>
          tab.id === activeTabId ? { ...tab, loadedFromDraft: false } : tab
        ))
        return
      }

      // Skip merge if tab has unsaved changes - never overwrite user edits with snapshot data
      if (activeTab?.hasUnsavedChanges) {
        return
      }

      // Subsequent renders (mock values changed): merge snapshot props with existing elements
      // This preserves user-added children while updating props based on new mock values
      setTabs(prev => prev.map(tab => {
        if (tab.id !== activeTabId) return tab

        // Merge: keep existing children but update root element props from snapshot
        const mergedElements = mergeSnapshotWithExisting(tab.elements, snapshotElements)
        return { ...tab, elements: mergedElements }
      }))
    }
  }, [snapshotElements, activeTabId, activeTab?.type, activeTab?.snapshotComponentName, activeTab?.loadedFromDraft, activeTab?.hasUnsavedChanges])

  const onEditComponent = async (componentName: string, filePath: string) => {
    // Check if tab already exists for this file
    const existingTab = tabs.find(tab => tab.filePath === filePath)
    if (existingTab) {
      // Switch to existing tab
      setActiveTabId(existingTab.id)
      router.push(`?file=${encodeURIComponent(filePath)}`)
      return
    }

    // In read-only mode, use pre-generated snapshots (no dev server needed)
    if (readOnly) {
      const snapshotComponentName = `${componentName}Snapshot`

      // Check if snapshot exists
      if (!snapshots[snapshotComponentName]) {
        console.error(`Snapshot not found for ${componentName}. Run 'lunagraph generate-snapshots' to pre-generate snapshots.`)
        toast.error(`Component "${componentName}" snapshot not available`, {
          description: 'Run "lunagraph generate-snapshots" before deploying.'
        })
        return
      }

      // Use pre-generated metadata if available
      const metadata = snapshotMetadata[componentName]
      const allSnapshotProps = metadata?.snapshotProps || []
      const variables = allSnapshotProps.map(p => p.name)
      const props = allSnapshotProps.filter(p => p.source === 'originalProp').map(p => p.name)
      const initialValues: Record<string, any> = {}
      for (const prop of allSnapshotProps) {
        if (prop.initialValue !== undefined) {
          initialValues[prop.name] = prop.initialValue
        }
      }

      const newTab: EditorTab = {
        id: generatePrefixedId('file'),
        name: componentName,
        type: 'file',
        filePath,
        elements: [], // Will be populated by useSnapshotRenderer
        snapshotComponentName,
        snapshotProps: allSnapshotProps,
        mockValues: metadata?.initialMockValues || {},
        variables,
        props,
        initialValues,
        sourceCode: metadata?.sourceCode, // Pre-loaded source code for read-only mode
        internalComponents: metadata?.internalComponents, // Internal components for read-only mode
      }

      setTabs(prev => [...prev, newTab])
      setActiveTabId(newTab.id)
      router.push(`?file=${encodeURIComponent(filePath)}`)
      return
    }

    // Dev mode: use dev server to create snapshot dynamically
    // Check for existing draft
    const draftResult = await loadDraft(componentName)

    // Create snapshot from dev server
    // This generates .lunagraph/snapshots/ComponentName.snapshot.tsx
    // and updates .lunagraph/snapshots/index.ts (which triggers hot reload)
    // Pass componentName so the server extracts the correct component from files with multiple components
    const result = await createSnapshot(filePath, componentName)

    if (!result.success) {
      console.error('Failed to create snapshot:', result.error)
      // Still create tab but with empty data
      const newTab: EditorTab = {
        id: generatePrefixedId('file'),
        name: componentName,
        type: 'file',
        filePath,
        elements: []
      }
      setTabs(prev => [...prev, newTab])
      setActiveTabId(newTab.id)
      router.push(`?file=${encodeURIComponent(filePath)}`)
      return
    }

    // Create new tab with snapshot data
    // Elements will be populated when hot reload completes and useSnapshotRenderer picks up the new snapshot

    // Extract variable names and props from snapshotProps for StatePanel
    // Include all props - those with import defaults will use their built-in defaults
    const allSnapshotProps = result.snapshotProps || []
    const variables = allSnapshotProps.map(p => p.name)
    const props = allSnapshotProps.filter(p => p.source === 'originalProp').map(p => p.name)
    const initialValues: Record<string, any> = {}
    for (const prop of allSnapshotProps) {
      if (prop.initialValue !== undefined) {
        initialValues[prop.name] = prop.initialValue
      }
    }

    const newTab: EditorTab = {
      id: generatePrefixedId('file'),
      name: componentName,
      type: 'file',
      filePath,
      elements: [], // Will be populated by snapshot rendering after hot reload
      snapshotComponentName: result.snapshotComponentName,
      snapshotProps: result.snapshotProps,
      mockValues: result.initialMockValues || {},
      variables,
      props,
      initialValues,
      internalComponents: result.internalComponents,
    }

    // Handle draft loading
    if (draftResult.success && draftResult.draft) {
      if (draftResult.sourceModifiedSinceDraft) {
        // Source was modified since draft - show conflict dialog
        setDraftConflict({
          isOpen: true,
          componentName,
          filePath,
          draftElements: draftResult.draft.elements,
          draftMockValues: draftResult.draft.mockValues,
          pendingTab: newTab,
        })
        return // Don't add tab yet - wait for user choice
      } else {
        // Draft is valid - load it with hasUnsavedChanges = true
        newTab.elements = draftResult.draft.elements
        newTab.mockValues = draftResult.draft.mockValues
        newTab.hasUnsavedChanges = true
        newTab.lastSavedElements = '' // Empty so any change is detected
        newTab.loadedFromDraft = true // Skip snapshot merge on first render
        // Mark this tab as initialized so snapshot doesn't overwrite draft
        initializedTabsRef.current.add(newTab.id)
      }
    }

    setTabs(prev => [...prev, newTab])
    setActiveTabId(newTab.id)
    router.push(`?file=${encodeURIComponent(filePath)}`)
  }

  // Handler for editing internal components (non-exported components in the same file)
  const onEditInternalComponent = async (
    componentName: string,
    parentFilePath: string,
    startLine: number,
    endLine: number
  ) => {
    // Check if tab already exists for this internal component
    const existingTab = tabs.find(tab =>
      tab.isInternalComponent &&
      tab.internalComponentName === componentName &&
      tab.parentFilePath === parentFilePath
    )
    if (existingTab) {
      // Switch to existing tab
      setActiveTabId(existingTab.id)
      router.push(`?file=${encodeURIComponent(parentFilePath)}&internal=${encodeURIComponent(componentName)}`)
      return
    }

    // In read-only mode, use pre-generated snapshots (no dev server needed)
    if (readOnly) {
      toast.error('Editing internal components is not available in read-only mode')
      return
    }

    // Create snapshot for the internal component
    // Pass the internal component name so the server extracts that specific component
    const result = await createSnapshot(parentFilePath, componentName)

    if (!result.success) {
      console.error('Failed to create snapshot for internal component:', result.error)
      toast.error(`Failed to open ${componentName}: ${result.error}`)
      return
    }

    // Extract variable names and props from snapshotProps for StatePanel
    const allSnapshotProps = result.snapshotProps || []
    const variables = allSnapshotProps.map(p => p.name)
    const props = allSnapshotProps.filter(p => p.source === 'originalProp').map(p => p.name)
    const initialValues: Record<string, any> = {}
    for (const prop of allSnapshotProps) {
      if (prop.initialValue !== undefined) {
        initialValues[prop.name] = prop.initialValue
      }
    }

    const newTab: EditorTab = {
      id: generatePrefixedId('internal'),
      name: componentName,
      type: 'file',
      filePath: `${parentFilePath}#${componentName}`, // Virtual path for the internal component
      elements: [], // Will be populated by snapshot rendering after hot reload
      snapshotComponentName: result.snapshotComponentName,
      snapshotProps: result.snapshotProps,
      mockValues: result.initialMockValues || {},
      variables,
      props,
      initialValues,
      // Internal component specific fields
      isInternalComponent: true,
      parentFilePath,
      internalComponentName: componentName,
      internalComponentRange: { startLine, endLine },
    }

    setTabs(prev => [...prev, newTab])
    setActiveTabId(newTab.id)
    router.push(`?file=${encodeURIComponent(parentFilePath)}&internal=${encodeURIComponent(componentName)}`)

    toast(`Editing internal component: ${componentName}`)
  }

  // Handle draft conflict resolution
  const onDraftConflictLoadFromCode = async () => {
    if (!draftConflict?.pendingTab) return

    // Delete the stale draft
    await deleteDraft(draftConflict.componentName)

    // Remove from draft list (updates AssetsPanel badges)
    setDraftComponentNames(prev => {
      const next = new Set(prev)
      next.delete(draftConflict.componentName)
      return next
    })

    // Add the tab normally (snapshot will populate elements)
    setTabs(prev => [...prev, draftConflict.pendingTab!])
    setActiveTabId(draftConflict.pendingTab.id)
    router.push(`?file=${encodeURIComponent(draftConflict.filePath)}`)

    setDraftConflict(null)
    toast('Loaded fresh from code. Draft discarded.')
  }

  const onDraftConflictContinueWithDraft = () => {
    if (!draftConflict?.pendingTab) return

    // Load the draft elements and mark as initialized
    const tabWithDraft: EditorTab = {
      ...draftConflict.pendingTab,
      elements: draftConflict.draftElements,
      mockValues: draftConflict.draftMockValues,
      hasUnsavedChanges: true,
      lastSavedElements: '',
      loadedFromDraft: true, // Skip snapshot merge on first render
    }
    initializedTabsRef.current.add(tabWithDraft.id)

    setTabs(prev => [...prev, tabWithDraft])
    setActiveTabId(tabWithDraft.id)
    router.push(`?file=${encodeURIComponent(draftConflict.filePath)}`)

    setDraftConflict(null)
    toast('Continuing with draft. Save to code when ready.')
  }

  const onTabChange = (tabId: string) => {
    setActiveTabId(tabId)
    const tab = tabs.find(t => t.id === tabId)
    if (tab?.type === 'file' && tab.filePath) {
      router.push(`?file=${encodeURIComponent(tab.filePath)}`)
    } else {
      router.push('/editor')
    }
  }

  const onTabClose = (tabId: string) => {
    const tabIndex = tabs.findIndex(t => t.id === tabId)
    const newTabs = tabs.filter(t => t.id !== tabId)
    setTabs(newTabs)

    // If closing active tab, switch to adjacent tab
    if (tabId === activeTabId) {
      const newActiveTab = newTabs[Math.max(0, tabIndex - 1)]
      setActiveTabId(newActiveTab.id)
      if (newActiveTab.type === 'file' && newActiveTab.filePath) {
        router.push(`?file=${encodeURIComponent(newActiveTab.filePath)}`)
      } else {
        router.push('/editor')
      }
    }
  }

  // Configure sensors with activation constraint to allow double-click
  // Uses PanAwarePointerSensor which doesn't activate when Space is pressed,
  // allowing Space+drag to pan the canvas without dragging elements
  const sensors = useSensors(
    useSensor(PanAwarePointerSensor, {
      activationConstraint: {
        distance: 5, // Drag only starts after moving 5px
      },
    })
  );

  const onDragElement = (
    draggedId: string,
    targetId: string | null,
    position: "before" | "after" | "inside"
  ) => {
    if (!activeTabId) return

    // Record original position for undo
    const fromParentId = findParentId(elements, draggedId)
    const fromSiblings = fromParentId
      ? (findElement(elements, fromParentId) as any)?.children || []
      : elements
    const fromIndex = fromSiblings.findIndex((el: FEElement) => el.id === draggedId)

    // Apply the drag
    const newElements = dragElement(elements, draggedId, targetId, position);
    setElements(newElements);

    // Calculate target parent and index
    let toParentId: string | null = null
    let toIndex = 0

    if (position === 'inside' && targetId) {
      toParentId = targetId
      // Will be at end of target's children
      const target = findElement(elements, targetId)
      toIndex = target && 'children' in target ? (target.children?.length || 0) : 0
    } else if (targetId) {
      // before/after a sibling
      toParentId = findParentId(elements, targetId)
      const toSiblings = toParentId
        ? (findElement(elements, toParentId) as any)?.children || []
        : elements
      const targetIndex = toSiblings.findIndex((el: FEElement) => el.id === targetId)
      toIndex = position === 'before' ? targetIndex : targetIndex + 1
    }

    // Record the move operation
    history.recordOperations(activeTabId, [{
      type: 'move',
      elementId: draggedId,
      fromParentId,
      toParentId,
      fromIndex: fromIndex >= 0 ? fromIndex : 0,
      toIndex,
    }])
  }

  // Callback for drag operations to push to history (without applying, since drag already applied)
  const onPushDragOperations = useCallback((ops: Operation[]) => {
    if (!activeTabId || ops.length === 0) return
    history.recordOperations(activeTabId, ops)
  }, [activeTabId, history])

  const {
    activeId,
    activeElement,
    activeElements,
    draggedIds,
    overId,
    isDragging,
    handleDragStart,
    handleDragMove,
    handleDragEnd,
    handleDragCancel,
  } = useDndCanvas({
    elements,
    setElements,
    onSelectElement: (id: string | null) => handleSelectElement(id, false),
    onDragElement,
    canvasScale: canvasZoom,
    selectedElementIds,
    hoverElementId,
    onPushOperations: onPushDragOperations,
  });

  const onAddElement = (element: FEElement) => {
    if (!activeTabId) return

    // If there's a selected element that can have children, insert into it
    if (selectedElementId) {
      const selectedElement = findElement(elementsRef.current, selectedElementId)
      if (selectedElement && hasChildren(selectedElement)) {
        // Insert as child of selected element (no canvas position needed)
        const { canvasPosition, ...elementWithoutPosition } = element as FEElement & { canvasPosition?: { x: number; y: number } }
        const childrenCount = (selectedElement as any).children?.length || 0
        const op = createInsertOperation(elementWithoutPosition as FEElement, selectedElementId, childrenCount)
        const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
        setElements(newElements)
        return
      }
    }

    // No valid parent selected - place element at root in visible area of canvas
    let canvasPosition = element.canvasPosition ?? { x: 100, y: 100 };
    if (viewportRef.current && canvasRef.current) {
      const viewportRect = viewportRef.current.getBoundingClientRect();
      const canvasRect = canvasRef.current.getBoundingClientRect();
      const { scale } = canvasTransformRef.current;
      // Target screen position: offset from viewport top-left (more Y padding for tabs)
      const screenX = viewportRect.left + 100;
      const screenY = viewportRect.top + 150;
      // Convert to canvas coords using canvas's transformed rect
      canvasPosition = {
        x: (screenX - canvasRect.left) / scale,
        y: (screenY - canvasRect.top) / scale,
      };
    }
    const elementWithPosition = { ...element, canvasPosition }
    const op = createInsertOperation(elementWithPosition, null, elementsRef.current.length)
    const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
    setElements(newElements)
  }

  const onResizeElement = useCallback((
    elementId: string,
    size: { width: number; height: number },
    pos?: { x: number; y: number }
  ) => {
    if (!activeTabId) return
    // For resize, we update styles (width/height) and optionally position
    // This is a compound operation - we'll use set_styles for now
    const element = findElement(elementsRef.current, elementId)
    if (!element) return

    const newStyles = {
      ...(element.styles || {}),
      width: size.width,
      height: size.height,
    }

    const ops: Operation[] = []

    const styleOp = createSetStylesOperation(elementsRef.current, elementId, newStyles)
    if (styleOp) ops.push(styleOp)

    if (pos) {
      const posOp = createSetPositionOperation(elementsRef.current, elementId, pos)
      if (posOp) ops.push(posOp)
    }

    if (ops.length > 0) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, ops)
      setElements(newElements)
    }
  }, [activeTabId, history, setElements])

  // Undo/Redo handlers
  const onUndo = useCallback(() => {
    if (!activeTabId) return
    const newElements = history.undo(activeTabId, elementsRef.current)
    setElements(newElements)
  }, [activeTabId, history, setElements])

  const onRedo = useCallback(() => {
    if (!activeTabId) return
    const newElements = history.redo(activeTabId, elementsRef.current)
    setElements(newElements)
  }, [activeTabId, history, setElements])

  const onDeleteElement = (elementId: string) => {
    if (!activeTabId) return
    const op = createRemoveOperation(elementsRef.current, elementId)
    if (op) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
      setElements(newElements)
    }
    setSelectedElementIds(prev => {
      const next = new Set(prev)
      next.delete(elementId)
      return next
    })
  }

  // Batch delete for multi-select
  const onDeleteElements = (elementIds: Set<string>) => {
    if (!activeTabId || elementIds.size === 0) return

    // Build all remove operations from current state
    const ops: Operation[] = []
    let currentElements = elementsRef.current

    for (const id of elementIds) {
      const op = createRemoveOperation(currentElements, id)
      if (op) {
        ops.push(op)
        // Update currentElements so next op sees correct state
        currentElements = removeElement(currentElements, id).tree
      }
    }

    if (ops.length > 0) {
      // Push all ops as single history entry
      const newElements = history.pushOperation(activeTabId, elementsRef.current, ops)
      setElements(newElements)
    }

    setSelectedElementIds(new Set())
  }

  const onDuplicateElement = (elementId: string) => {
    if (!activeTabId) return
    const element = findElement(elementsRef.current, elementId)
    if (!element) return

    // Clone with new IDs
    const duplicate = cloneElementWithNewIds(element)

    // Find where to insert (after original)
    const parentId = findParentId(elementsRef.current, elementId)
    const siblings = parentId
      ? (findElement(elementsRef.current, parentId) as any)?.children || []
      : elementsRef.current
    const index = siblings.findIndex((el: FEElement) => el.id === elementId)

    const op = createInsertOperation(duplicate, parentId, index + 1)
    const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
    setElements(newElements)
  }

  const onDoubleClickDrillIn = (elementId: string, x: number, y: number) => {
    // Check if the double-clicked element is a component - if so, open it for editing
    const element = findElement(elements, elementId);
    if (element?.type === 'component') {
      const componentElement = element as ComponentElement;
      const componentName = componentElement.componentName;
      const componentInfo = mergedComponentIndex[componentName];
      if (componentInfo?.path) {
        onEditComponent(componentName, componentInfo.path);
        return;
      }
    }

    // Find all elements at the click position
    const elementsAtPoint = document.elementsFromPoint(x, y);
    const elementIds: string[] = [];

    for (const el of elementsAtPoint) {
      const id = el.getAttribute('data-element-id');
      if (id) {
        elementIds.push(id);
      }
    }

    // Find the element that was double-clicked
    const clickedIndex = elementIds.indexOf(elementId);
    if (clickedIndex === -1 || clickedIndex === 0) {
      // Can't drill in further (already at deepest level or element not found)
      return;
    }

    // Select the next deeper element (one level down in the hierarchy)
    const childId = elementIds[clickedIndex - 1];
    setSelectedElementIds(new Set([childId]));
  }

  const onEditText = (elementId: string, text: string) => {
    if (!activeTabId) return
    const op = createSetTextOperation(elementsRef.current, elementId, text)
    if (op) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
      setElements(newElements)
    }
  }

  const onUpdateElementStyles = (elementId: string, styles: React.CSSProperties) => {
    if (!activeTabId) return
    const op = createSetStylesOperation(elementsRef.current, elementId, styles)
    if (op) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
      setElements(newElements)
    }
  }

  const onUpdateElementProps = (elementId: string, props: Record<string, any>) => {
    if (!activeTabId) return
    const op = createSetPropsOperation(elementsRef.current, elementId, props)
    if (op) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
      setElements(newElements)
    }
  }

  // Batch update props for multiple elements (e.g., adding Tailwind classes to all selected)
  const onUpdateMultipleElementsProps = (
    elementIds: Set<string>,
    propsUpdater: (currentProps: Record<string, any>) => Record<string, any>
  ) => {
    if (!activeTabId || elementIds.size === 0) return

    const operations: any[] = []
    for (const elementId of elementIds) {
      const element = findElement(elementsRef.current, elementId)
      if (!element || element.type === 'text') continue

      const currentProps = (element as any).props || {}
      const newProps = propsUpdater(currentProps)
      const op = createSetPropsOperation(elementsRef.current, elementId, newProps)
      if (op) operations.push(op)
    }

    if (operations.length > 0) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, operations)
      setElements(newElements)
    }
  }

  // Batch update styles for multiple elements
  const onUpdateMultipleElementsStyles = (
    elementIds: Set<string>,
    stylesUpdater: (currentStyles: React.CSSProperties) => React.CSSProperties
  ) => {
    if (!activeTabId || elementIds.size === 0) return

    const operations: any[] = []
    for (const elementId of elementIds) {
      const element = findElement(elementsRef.current, elementId)
      if (!element) continue

      const currentStyles = element.styles || {}
      const newStyles = stylesUpdater(currentStyles)
      const op = createSetStylesOperation(elementsRef.current, elementId, newStyles)
      if (op) operations.push(op)
    }

    if (operations.length > 0) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, operations)
      setElements(newElements)
    }
  }

  const onReplaceElement = (oldElementId: string, newElement: FEElement) => {
    if (!activeTabId) return
    const op = createReplaceOperation(elementsRef.current, oldElementId, newElement)
    if (op) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
      setElements(newElements)
    }
  }

  const onCopyElement = async (elementId: string) => {
    const element = findElement(elementsRef.current, elementId);
    if (element) {
      await copyElementToClipboard(element);
    }
  }

  // Batch copy for multi-select
  const onCopyElements = async (elementIds: Set<string>) => {
    if (elementIds.size === 0) return;

    const elementsToCopy: FEElement[] = [];
    for (const id of elementIds) {
      const element = findElement(elementsRef.current, id);
      if (element) {
        elementsToCopy.push(element);
      }
    }

    if (elementsToCopy.length === 0) return;

    // Copy to clipboard with multi format
    const clipboardData = {
      __lunagraph: true,
      __multi: true,
      elements: elementsToCopy
    };
    try {
      await navigator.clipboard.writeText(JSON.stringify(clipboardData));
    } catch (err) {
      console.error('Failed to copy to clipboard:', err);
    }
  }

  const onCutElement = async (elementId: string) => {
    if (!activeTabId) return;
    const element = findElement(elementsRef.current, elementId);
    if (!element) return;

    // Copy to clipboard first
    const copied = await copyElementToClipboard(element);
    if (!copied) return;

    // Delete the element with undo support
    const op = createRemoveOperation(elementsRef.current, elementId);
    if (op) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, op);
      setElements(newElements);
    }
    setSelectedElementIds(prev => {
      const next = new Set(prev);
      next.delete(elementId);
      return next;
    });
  }

  // Batch cut for multi-select
  const onCutElements = async (elementIds: Set<string>) => {
    if (!activeTabId || elementIds.size === 0) return;

    // For multi-select, copy all elements as an array
    const elementsToCut: FEElement[] = [];
    for (const id of elementIds) {
      const element = findElement(elementsRef.current, id);
      if (element) {
        elementsToCut.push(element);
      }
    }

    if (elementsToCut.length === 0) return;

    // Copy to clipboard (for multi-select, we'll copy a special format)
    const clipboardData = {
      __lunagraph: true,
      __multi: true,
      elements: elementsToCut
    };
    try {
      await navigator.clipboard.writeText(JSON.stringify(clipboardData));
    } catch (err) {
      console.error('Failed to copy to clipboard:', err);
      return;
    }

    // Delete all elements with undo support
    const ops: Operation[] = [];
    let currentElements = elementsRef.current;

    for (const id of elementIds) {
      const op = createRemoveOperation(currentElements, id);
      if (op) {
        ops.push(op);
        currentElements = removeElement(currentElements, id).tree;
      }
    }

    if (ops.length > 0) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, ops);
      setElements(newElements);
    }

    setSelectedElementIds(new Set());
  }

  const onPasteElement = async () => {
    if (!activeTabId) return;

    // Try to read clipboard text first to check for multi-element paste
    let clipboardText: string | null = null;
    try {
      clipboardText = await navigator.clipboard.readText();
    } catch {
      // Fall through to single element paste
    }

    // Check for multi-element paste format
    if (clipboardText) {
      try {
        const parsed = JSON.parse(clipboardText);
        if (parsed.__lunagraph && parsed.__multi && Array.isArray(parsed.elements)) {
          // Multi-element paste
          await pasteMultipleElements(parsed.elements);
          return;
        }
      } catch {
        // Not valid JSON, fall through to single element paste
      }
    }

    // Single element paste (or image paste via readElementFromClipboard)
    const result = await readElementFromClipboard(readOnly ? undefined : devServerUrl);
    if (result.error) {
      toast.error(result.errorMessage || 'Failed to paste image');
      return;
    }
    if (!result.element) return;
    const clipboardElement = result.element;

    // Clone with new IDs
    const pastedElement = cloneElementWithNewIds(clipboardElement);

    if (!selectedElementId) {
      // No element selected: paste at root level
      // Calculate canvas position - visible area
      let canvasPosition = { x: 20, y: 20 };
      if (viewportRef.current && canvasRef.current) {
        const viewportRect = viewportRef.current.getBoundingClientRect();
        const canvasRect = canvasRef.current.getBoundingClientRect();
        const { scale } = canvasTransformRef.current;
        // Target screen position: offset from viewport top-left (more Y padding for tabs)
        const screenX = viewportRect.left + 100;
        const screenY = viewportRect.top + 150;
        // Convert to canvas coords using canvas's transformed rect
        canvasPosition = {
          x: (screenX - canvasRect.left) / scale,
          y: (screenY - canvasRect.top) / scale,
        };
      }
      pastedElement.canvasPosition = canvasPosition;

      // Create insert operation at root level
      const op = createInsertOperation(pastedElement, null, elementsRef.current.length);
      const newElements = history.pushOperation(activeTabId, elementsRef.current, op);
      setElements(newElements);
    } else {
      // Element selected: paste as child
      const parent = findElement(elementsRef.current, selectedElementId);
      if (!parent || !hasChildren(parent)) {
        // Can't paste into text/icon node - paste at root instead
        pastedElement.canvasPosition = { x: 20, y: 20 };
        const op = createInsertOperation(pastedElement, null, elementsRef.current.length);
        const newElements = history.pushOperation(activeTabId, elementsRef.current, op);
        setElements(newElements);
        return;
      }

      // Insert as last child of selected element
      const childrenCount = (parent as any).children?.length || 0;
      const op = createInsertOperation(pastedElement, selectedElementId, childrenCount);
      const newElements = history.pushOperation(activeTabId, elementsRef.current, op);
      setElements(newElements);
    }
  }

  // Helper for pasting multiple elements (from multi-select cut/copy)
  const pasteMultipleElements = async (elementsToPaste: FEElement[]) => {
    if (!activeTabId || elementsToPaste.length === 0) return;

    // Calculate base canvas position
    let basePosition = { x: 20, y: 20 };
    if (viewportRef.current && canvasRef.current) {
      const viewportRect = viewportRef.current.getBoundingClientRect();
      const canvasRect = canvasRef.current.getBoundingClientRect();
      const { scale } = canvasTransformRef.current;
      const screenX = viewportRect.left + 100;
      const screenY = viewportRect.top + 150;
      basePosition = {
        x: (screenX - canvasRect.left) / scale,
        y: (screenY - canvasRect.top) / scale,
      };
    }

    // Find the original bounding box of all elements to calculate relative positions
    let minX = Infinity, minY = Infinity;
    for (const el of elementsToPaste) {
      if (el.canvasPosition) {
        minX = Math.min(minX, el.canvasPosition.x);
        minY = Math.min(minY, el.canvasPosition.y);
      }
    }
    if (minX === Infinity) minX = 0;
    if (minY === Infinity) minY = 0;

    // Clone all elements with new IDs and adjusted positions
    const ops: Operation[] = [];
    const newIds: string[] = [];

    for (const el of elementsToPaste) {
      const cloned = cloneElementWithNewIds(el);

      // Adjust position relative to base position, preserving relative layout
      if (el.canvasPosition) {
        cloned.canvasPosition = {
          x: basePosition.x + (el.canvasPosition.x - minX),
          y: basePosition.y + (el.canvasPosition.y - minY),
        };
      } else {
        cloned.canvasPosition = basePosition;
      }

      ops.push(createInsertOperation(cloned, null, elementsRef.current.length + ops.length));
      newIds.push(cloned.id);
    }

    if (ops.length > 0) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, ops);
      setElements(newElements);
      // Select all pasted elements
      setSelectedElementIds(new Set(newIds));
    }
  }

  const onCreateComponent = async (componentName: string) => {
    if (!selectedElementId) {
      console.error('Cannot create component: no element selected')
      return
    }

    // Determine if we're in a canvas tab or file tab
    const isCanvasTab = activeTab?.type === 'canvas' && activeTab.canvasId
    const isFileTab = activeTab?.type === 'file' && activeTab.filePath

    if (!isCanvasTab && !isFileTab) {
      console.error('Cannot create component: not in a valid canvas or file tab')
      return
    }

    // Find the selected element
    const element = findElement(elements, selectedElementId)
    if (!element) {
      console.error('Selected element not found')
      return
    }

    // Determine target file path based on tab type
    let targetFilePath: string
    if (isCanvasTab) {
      targetFilePath = `.lunagraph/canvases/${activeTab.canvasId}/components/${componentName}.tsx`
    } else {
      // File tab: create sibling component in the same directory
      const sourceDir = activeTab.filePath!.replace(/\/[^/]+$/, '') // Get directory
      targetFilePath = `${sourceDir}/${componentName}.tsx`
    }

    // Generate component code
    const code = generateCompleteFile({
      componentName,
      elements: [element as CodegenFEElement],
      componentIndex,
      targetFilePath
    })

    // Save component to dev server
    let result: { success: boolean; error?: string; componentName?: string; path?: string }
    if (isCanvasTab) {
      result = await createComponent({
        canvasId: activeTab.canvasId!,
        componentName,
        code
      })
    } else {
      result = await createComponentFromFile({
        sourceFilePath: activeTab.filePath!,
        componentName,
        code
      })
    }

    if (!result.success) {
      console.error('Failed to create component:', result.error)
      toast.error(`Failed to create component: ${result.error}`)
      return
    }

    toast.success(`Created component: ${componentName}`)

    // Replace element in canvas with component reference
    const componentElement: FEElement = {
      id: generatePrefixedId('component'),
      type: 'component',
      componentName,
      props: {},
      ...(!hasChildren(element) || element.canvasPosition ? { canvasPosition: element.canvasPosition } : {}),
    };

    const op = createReplaceOperation(elementsRef.current, selectedElementId, componentElement)
    if (op && activeTabId) {
      const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
      setElements(newElements)
    }
    setSelectedElementIds(new Set())
  }

  const onWrapInDiv = useCallback(() => {
    if (selectedElementIds.size === 0 || !activeTabId) return

    const result = wrapElementsInDiv(elementsRef.current, selectedElementIds)
    if (result) {
      // For wrap operation, we'll use a snapshot-based approach for now
      // Since it's complex (multiple removes + one insert), we record it as operations
      // that when undone would: remove wrapper, restore all wrapped elements

      // Build operations: for each wrapped element, create remove op, then one insert for wrapper
      const ops: Operation[] = []

      // Remove operations for each wrapped element (we need their positions before wrap)
      for (const id of selectedElementIds) {
        const removeOp = createRemoveOperation(elementsRef.current, id)
        if (removeOp) ops.push(removeOp)
      }

      // Find where wrapper was inserted (first removed element's position)
      const firstId = Array.from(selectedElementIds)[0]
      const parentId = findParentId(elementsRef.current, firstId)
      const siblings = parentId
        ? (findElement(elementsRef.current, parentId) as any)?.children || []
        : elementsRef.current
      const index = siblings.findIndex((el: FEElement) => el.id === firstId)

      // Create insert operation for the wrapper
      // Find the wrapper element in the result tree
      const findWrapper = (els: FEElement[]): FEElement | null => {
        for (const el of els) {
          if (el.id === result.wrapperId) return el
          if (hasChildren(el) && el.children) {
            const found = findWrapper(el.children)
            if (found) return found
          }
        }
        return null
      }
      const wrapperElement = findWrapper(result.tree)
      if (wrapperElement) {
        ops.push(createInsertOperation(wrapperElement, parentId, index >= 0 ? index : 0))
      }

      // Apply the result directly (wrapElementsInDiv already computed it)
      // but record the operations for undo
      if (ops.length > 0) {
        // Push operations to history but use pre-computed result
        history.pushOperation(activeTabId, elementsRef.current, ops)
      }
      setElements(result.tree)
      // Select the new wrapper
      setSelectedElementIds(new Set([result.wrapperId]))
    }
  }, [selectedElementIds, activeTabId, history, setElements])

  const onUpdateMockValue = useCallback((name: string, value: any) => {
    setTabs(prev => prev.map(tab => {
      if (tab.id !== activeTabId || tab.type !== 'file') return tab

      const newMockValues = {
        ...tab.mockValues,
        [name]: value
      }
      return {
        ...tab,
        mockValues: newMockValues
      }
    }))
  }, [activeTabId])

  const onReloadFile = useCallback(async (filePath: string) => {
    // Reload the file to get updated content after save
    const result = await loadFile(filePath)

    if (!result.success) {
      console.error('Failed to reload file:', result.error)
      return
    }

    // Find all tabs that should be affected:
    // 1. The tab with this exact filePath (normal save)
    // 2. Internal component tabs with this parentFilePath (internal component save)
    // 3. Parent component tabs when an internal component was saved
    const tabsToReset = tabs.filter(t => {
      // Direct match
      if (t.filePath === filePath) return true
      // Internal component in this file
      if (t.isInternalComponent && t.parentFilePath === filePath) return true
      // Parent tab for this internal component
      if (!t.isInternalComponent && t.filePath === filePath) return true
      return false
    })

    for (const tabToReset of tabsToReset) {
      // Clear from initialized set so next render will be fresh
      initializedTabsRef.current.delete(tabToReset.id)
      // Clear last snapshot ref to allow update
      lastSnapshotRef.current = ''
      // Delete the draft since we just saved to code
      if (tabToReset.name) {
        deleteDraft(tabToReset.name)
        // Remove from draft list
        setDraftComponentNames(prev => {
          const next = new Set(prev)
          next.delete(tabToReset.name)
          return next
        })
      }
    }

    // Update all affected tabs
    // For internal component tabs: mark as clean
    // For parent tabs that use the file: refresh snapshot but keep draft status
    setTabs(prev => prev.map(tab => {
      // Check if this tab should be updated
      const isDirectMatch = tab.filePath === filePath
      const isInternalOfFile = tab.isInternalComponent && tab.parentFilePath === filePath
      const isParentOfInternalSave = !tab.isInternalComponent && tab.filePath === filePath

      if (!isDirectMatch && !isInternalOfFile && !isParentOfInternalSave) return tab

      // For the tab that was just saved (direct match or internal component)
      if (isDirectMatch || (isInternalOfFile && activeTab?.id === tab.id)) {
        const currentElementsKey = JSON.stringify(tab.elements)
        return {
          ...tab,
          variables: result.variables,
          initialValues: result.initialValues,
          props: result.props,
          // Increment snapshotVersion to force re-render with new snapshot
          snapshotVersion: (tab.snapshotVersion || 0) + 1,
          // Keep existing mockValues - don't reset them after save
          // Mark as clean - just saved to code
          hasUnsavedChanges: false,
          lastSavedElements: currentElementsKey,
        }
      }

      // For parent tabs when an internal component was saved:
      // Refresh the snapshot but KEEP their draft status
      if (isParentOfInternalSave && tab.id !== activeTab?.id) {
        return {
          ...tab,
          // Increment snapshotVersion to force re-render with new snapshot
          // (so the updated internal component is reflected)
          snapshotVersion: (tab.snapshotVersion || 0) + 1,
          // Keep their draft status - they might have their own unsaved changes
        }
      }

      return tab
    }))
  }, [loadFile, tabs, deleteDraft, activeTab])

  // Discard draft and reset to snapshot (fresh from code)
  const handleDiscardDraft = useCallback(async () => {
    if (!activeTab || activeTab.type !== 'file' || !activeTab.name) return

    // Delete the draft from disk
    await deleteDraft(activeTab.name)

    // Remove from draft list (updates AssetsPanel badges)
    setDraftComponentNames(prev => {
      const next = new Set(prev)
      next.delete(activeTab.name)
      return next
    })

    // Clear from initialized set so next snapshot render will repopulate
    initializedTabsRef.current.delete(activeTab.id)
    // Clear last snapshot ref to allow update
    lastSnapshotRef.current = ''

    // Reset the tab to clean state - snapshot effect will repopulate elements
    setTabs(prev => prev.map(tab => {
      if (tab.id !== activeTab.id) return tab
      return {
        ...tab,
        hasUnsavedChanges: false,
        lastSavedElements: '',
        loadedFromDraft: false,
      }
    }))

    toast('Draft discarded. Loaded fresh from code.')
  }, [activeTab, deleteDraft])

  // Auto-save canvas on changes (skip in readOnly mode)
  useEffect(() => {
    // Skip auto-save in readOnly mode
    if (readOnly) return
    if (activeTab?.type !== 'canvas' || !activeTab.canvasId) return

    // Create current state snapshot
    const currentState = JSON.stringify({
      elements: activeTab.elements,
      zoom: canvasZoom,
    })

    // Skip if nothing changed
    if (currentState === lastSavedStateRef.current) return

    const timeout = setTimeout(async () => {
      const result = await saveCanvas({
        id: activeTab.canvasId,
        name: activeTab.name,
        elements: activeTab.elements,
        zoom: canvasZoom,
      })

      // Update elements with processed elements (base64 images converted to assets)
      if (result.success && result.canvas) {
        setTabs(prev => prev.map(tab =>
          tab.id === activeTab.id
            ? { ...tab, elements: result.canvas!.elements, canvasSaved: true }
            : tab
        ))
        setElements(result.canvas.elements)

        // Update element count in pages
        setPages(prev => prev.map(p =>
          p.id === activeTab.canvasId
            ? { ...p, elementCount: result.canvas!.elements.length }
            : p
        ))
      } else {
        // Mark as saved even if no processed elements returned
        setTabs(prev => prev.map(tab =>
          tab.id === activeTab.id ? { ...tab, canvasSaved: true } : tab
        ))
      }

      // Update last saved state
      lastSavedStateRef.current = currentState
    }, 1000) // Debounce 1s

    return () => clearTimeout(timeout)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab?.elements, canvasZoom, activeTab?.id, activeTab?.canvasId, readOnly])

  // Auto-save draft for file tabs when elements change (skip in readOnly mode)
  useEffect(() => {
    // Skip in readOnly mode
    if (readOnly) return
    // Only for file tabs with unsaved changes
    if (activeTab?.type !== 'file' || !activeTab.filePath || !activeTab.hasUnsavedChanges) return
    // Need elements to save
    if (!activeTab.elements || activeTab.elements.length === 0) return

    const timeout = setTimeout(async () => {
      const result = await saveDraft({
        componentName: activeTab.name,
        filePath: activeTab.filePath!,
        elements: activeTab.elements,
        mockValues: activeTab.mockValues,
      })
      // Update draft list when a draft is saved
      if (result.success) {
        setDraftComponentNames(prev => new Set([...prev, activeTab.name]))
      }
    }, 1000) // Debounce 1s

    return () => clearTimeout(timeout)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab?.elements, activeTab?.mockValues, activeTab?.id, activeTab?.hasUnsavedChanges, readOnly])

  // Handle keyboard shortcuts (delete, duplicate, copy, paste, create component, wrap)
  // Skip all edit shortcuts in readOnly mode
  useEffect(() => {
    // Skip all edit shortcuts in readOnly mode
    if (readOnly) return

    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't trigger shortcuts if user is typing in an input/textarea
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) {
        return;
      }

      // Delete: Delete or Backspace - works with multi-select
      if ((e.key === 'Delete' || e.key === 'Backspace') && selectedElementIds.size > 0) {
        e.preventDefault();
        // Delete all selected elements as a single undo-able action
        onDeleteElements(selectedElementIds);
      }

      // Undo: Cmd+Z (Mac) or Ctrl+Z (Windows/Linux)
      if ((e.metaKey || e.ctrlKey) && !e.shiftKey && e.key === 'z') {
        e.preventDefault();
        onUndo();
      }

      // Redo: Cmd+Shift+Z (Mac) or Ctrl+Shift+Z (Windows/Linux) or Ctrl+Y
      if (((e.metaKey || e.ctrlKey) && e.shiftKey && e.key === 'z') ||
        ((e.metaKey || e.ctrlKey) && e.key === 'y')) {
        e.preventDefault();
        onRedo();
      }

      // Duplicate: Cmd+D (Mac) or Ctrl+D (Windows/Linux) - single selection only
      if ((e.metaKey || e.ctrlKey) && e.key === 'd' && selectedElementId) {
        e.preventDefault();
        onDuplicateElement(selectedElementId);
      }

      // Copy: Cmd+C (Mac) or Ctrl+C (Windows/Linux) - works with multi-select
      if ((e.metaKey || e.ctrlKey) && e.key === 'c' && selectedElementIds.size > 0) {
        e.preventDefault();
        if (selectedElementIds.size === 1) {
          onCopyElement(Array.from(selectedElementIds)[0]);
        } else {
          onCopyElements(selectedElementIds);
        }
      }

      // Cut: Cmd+X (Mac) or Ctrl+X (Windows/Linux) - works with multi-select
      if ((e.metaKey || e.ctrlKey) && e.key === 'x' && selectedElementIds.size > 0) {
        e.preventDefault();
        if (selectedElementIds.size === 1) {
          onCutElement(Array.from(selectedElementIds)[0]);
        } else {
          onCutElements(selectedElementIds);
        }
      }

      // Paste: Cmd+V (Mac) or Ctrl+V (Windows/Linux)
      if ((e.metaKey || e.ctrlKey) && e.key === 'v') {
        e.preventDefault();
        onPasteElement();
      }

      // Create Component: Option+Cmd+K (Mac) or Alt+Ctrl+K (Windows/Linux) - single selection only
      if ((e.metaKey || e.ctrlKey) && e.altKey && e.key === 'k' && selectedElementId) {
        e.preventDefault();
        setShowCreateComponentModal(true);
      }

      // Wrap in div: Shift+A - works with multi-select
      if (e.shiftKey && e.key.toLowerCase() === 'a' && selectedElementIds.size > 0) {
        e.preventDefault();
        onWrapInDiv();
      }

      // Add selected elements to chat: Cmd+L
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'l' && selectedElementIds.size > 0) {
        e.preventDefault();
        chatPanelRef.current?.addSelectedElements();
      }

      // Arrow key reordering within flex containers - single selection only
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key) && selectedElementId && !e.metaKey && !e.ctrlKey && !e.altKey && !e.shiftKey) {
        const elements = activeTab?.elements || [];
        const parentId = findParentId(elements, selectedElementId);

        // Get parent's flex direction (default to column if at root or no explicit direction)
        let flexDirection: 'row' | 'column' = 'column';
        if (parentId) {
          const parent = findElement(elements, parentId);
          if (parent && 'styles' in parent && parent.styles?.flexDirection) {
            flexDirection = parent.styles.flexDirection as 'row' | 'column';
          }
        }

        // Determine if the arrow key matches the flex direction
        let offset: number | null = null;
        if (flexDirection === 'column') {
          if (e.key === 'ArrowUp') offset = -1;
          else if (e.key === 'ArrowDown') offset = 1;
        } else if (flexDirection === 'row') {
          if (e.key === 'ArrowLeft') offset = -1;
          else if (e.key === 'ArrowRight') offset = 1;
        }

        if (offset !== null) {
          e.preventDefault();
          const newElements = moveElementInSiblings(elements, selectedElementId, offset);
          if (newElements) {
            setElements(newElements);
          }
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedElementId, selectedElementIds, activeTab?.elements, setElements, readOnly, onUndo, onRedo]);

  return (
    <>

      <Toaster />
      {/* Note: snapshotRendererElement is now rendered inside Canvas for file tabs */}
      {/* For non-active file tabs, we still need to render their snapshot somewhere... */}
      {/* TODO: handle multiple file tabs open */}
      <CanvasLayout
        leftChildren={
          <div className="flex flex-col h-full overflow-hidden">
            {/* Pages Panel - like Figma's pages */}
            <PagesPanel
              pages={pages}
              activePageId={activePageId}
              onSelectPage={handleSelectPage}
              onCreatePage={handleCreatePage}
              onRenamePage={handleRenamePage}
              onDeletePage={handleDeletePage}
              readOnly={readOnly}
            />

            <Tabs defaultValue="layers" className="w-full gap-0 flex-1 overflow-hidden">
              <TabsList className="w-full p-2 overflow-auto scrollbar-hide" variant="simple">
                <TabsTrigger value="layers">Layers</TabsTrigger>
                <TabsTrigger value="insert">Insert</TabsTrigger>
                <TabsTrigger value="assets" className="relative gap-1">
                  Assets
                  {draftComponentNames.size > 0 && (
                    <span className="w-1.5 h-1.5 bg-yellow-500 rounded-full" />
                  )}
                </TabsTrigger>
                {Object.keys(iconLibraries).length > 0 && (
                  <TabsTrigger value="icons">Icons</TabsTrigger>
                )}
                {!readOnly && (
                  <TabsTrigger value="chat">Chat</TabsTrigger>
                )}
              </TabsList>
              <TabsContent value="layers" className="h-full overflow-hidden flex flex-col">
                <LayersPanel
                  elements={elements}
                  selectedElementIds={selectedElementIds}
                  onSelectElement={handleSelectElement}
                  onDragElement={onDragElement}
                  onUpdateText={onEditText}
                  onFocusElement={handleFocusElement}
                  readOnly={readOnly}
                />
              </TabsContent>
              <TabsContent value="insert" className="h-full overflow-hidden flex flex-col">
                <InsertPanel onAddElement={onAddElement} readOnly={readOnly} />
              </TabsContent>
              <TabsContent value="assets" className="h-full overflow-hidden flex flex-col">
                <AssetsPanel
                  onAddElement={onAddElement}
                  componentIndex={componentIndex}
                  onEditComponent={onEditComponent}
                  onEditInternalComponent={onEditInternalComponent}
                  readOnly={readOnly}
                  draftComponentNames={draftComponentNames}
                  internalComponents={
                    // When editing an internal component, show internal components from the parent tab
                    activeTab?.type === 'file'
                      ? (activeTab.isInternalComponent
                        ? tabs.find(t => t.filePath === activeTab.parentFilePath)?.internalComponents
                        : activeTab.internalComponents)
                      : undefined
                  }
                  activeFileName={activeTab?.type === 'file' ? activeTab.name : undefined}
                  activeFilePath={activeTab?.type === 'file' ? (activeTab.isInternalComponent ? activeTab.parentFilePath : activeTab.filePath) : undefined}
                />
              </TabsContent>
              {Object.keys(iconLibraries).length > 0 && (
                <TabsContent value="icons" className="h-full overflow-hidden flex flex-col">
                  <IconsPanel
                    iconLibraries={iconLibraries}
                    onAddElement={onAddElement}
                    readOnly={readOnly}
                  />
                </TabsContent>
              )}
              {!readOnly && (
                <TabsContent value="chat" className="h-full overflow-hidden flex flex-col">
                  <ChatPanel
                    ref={chatPanelRef}
                    elements={elements}
                    selectedElementIds={selectedElementIds}
                    availableComponents={Object.keys(componentIndex)}
                    devServerUrl={devServerUrl}
                    canvasId={activeTab?.type === 'canvas' ? activeTab.canvasId : undefined}
                    messages={chatMessages}
                    onMessagesChange={setChatMessages}
                    iconLibraryName={Object.keys(iconLibraries)[0]}
                    onSelectElement={(elementId) => {
                      setSelectedElementIds(new Set([elementId]))
                      setPendingElementToCenter(elementId)
                    }}
                    onToolResult={(result) => {
                      if (!activeTabId) return undefined

                      if (result.type === 'add_jsx') {
                        const payload = result.payload
                        const parsedElements = payload.elements as FEElement[]

                        if (!parsedElements || parsedElements.length === 0) {
                          return undefined
                        }

                        const ops: Operation[] = []
                        let xOffset = 100

                        for (const el of parsedElements) {
                          if (payload.parentId) {
                            // Find parent to get insertion index
                            const parent = findElement(elementsRef.current, payload.parentId)
                            const childCount = parent && 'children' in parent ? (parent.children?.length || 0) : 0
                            ops.push(createInsertOperation(el, payload.parentId, childCount))
                          } else {
                            el.canvasPosition = { x: xOffset, y: 100 }
                            xOffset += 50
                            ops.push(createInsertOperation(el, null, elementsRef.current.length + ops.filter(o => o.type === 'insert').length))
                          }
                        }

                        if (ops.length > 0) {
                          const newElements = history.pushOperation(activeTabId, elementsRef.current, ops)
                          setElements(newElements)
                        }

                        return parsedElements[0]?.id
                      } else if (result.type === 'update_jsx') {
                        const payload = result.payload
                        const { elementId, newElement } = payload as { elementId: string; newElement: FEElement }

                        if (!newElement) return undefined

                        // Preserve canvas position if it exists
                        const oldElement = findElement(elementsRef.current, elementId)
                        if (oldElement && 'canvasPosition' in oldElement && oldElement.canvasPosition) {
                          newElement.canvasPosition = oldElement.canvasPosition
                        }

                        // Use replace operation for undo support
                        const op = createReplaceOperation(elementsRef.current, elementId, newElement)
                        if (op) {
                          const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
                          setElements(newElements)
                        }

                        return newElement.id
                      } else if (result.type === 'delete_element') {
                        const op = createRemoveOperation(elementsRef.current, result.payload.elementId)
                        if (op) {
                          const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
                          setElements(newElements)
                        }
                        return result.payload.elementId
                      } else if (result.type === 'replace_with_component') {
                        const { elementId, componentName, props } = result.payload as {
                          elementId: string
                          componentName: string
                          props?: Record<string, any>
                        }

                        // Find the old element to preserve position
                        const oldElement = findElement(elementsRef.current, elementId)

                        // Create a component element
                        const componentElement: FEElement = {
                          id: elementId, // Keep the same ID
                          type: 'component',
                          componentName,
                          props: props || {},
                          styles: {},
                          canvasPosition: oldElement && 'canvasPosition' in oldElement
                            ? oldElement.canvasPosition
                            : undefined
                        }

                        // Replace the element
                        const op = createReplaceOperation(elementsRef.current, elementId, componentElement)
                        if (op) {
                          const newElements = history.pushOperation(activeTabId, elementsRef.current, op)
                          setElements(newElements)
                        }

                        return elementId
                      }
                      return undefined
                    }}
                  />
                </TabsContent>
              )}
            </Tabs>
          </div>
        }
        rightChildren={
          <div className="h-full flex flex-col overflow-hidden">
            <Tabs defaultValue="element" className="h-full flex flex-col">
              <TabsList className="w-full p-2" variant="simple">
                <TabsTrigger value="element">Element</TabsTrigger>
                <TabsTrigger value="state">State</TabsTrigger>
              </TabsList>
              <TabsContent value="state" className="flex-1 overflow-hidden">
                <StatePanel
                  variables={activeTab?.variables || []}
                  mockValues={activeTab?.mockValues || {}}
                  initialValues={activeTab?.initialValues || {}}
                  props={activeTab?.props || []}
                  onUpdateMockValue={onUpdateMockValue}
                  readOnly={readOnly}
                />
              </TabsContent>
              <TabsContent value="element" className="flex-1 overflow-hidden flex flex-col">
                <PropsPanel
                  selectedElementId={selectedElementId}
                  elements={elements}
                  componentIndex={mergedComponentIndex}
                  iconLibraries={iconLibraries}
                  onUpdateElementProps={onUpdateElementProps}
                  onReplaceElement={onReplaceElement}
                  onOpenComponent={onEditComponent}
                  renderMode={activeTab?.renderMode}
                  readOnly={readOnly}
                />
                <StylesPanelTabs
                  selectedElementId={selectedElementId}
                  selectedElementIds={selectedElementIds}
                  elements={elements}
                  onUpdateElementStyles={onUpdateElementStyles}
                  onUpdateElementProps={onUpdateElementProps}
                  onUpdateMultipleElementsProps={onUpdateMultipleElementsProps}
                  onUpdateMultipleElementsStyles={onUpdateMultipleElementsStyles}
                  onCreateComponent={() => setShowCreateComponentModal(true)}
                  renderMode={activeTab?.renderMode}
                  readOnly={readOnly}
                />
              </TabsContent>
            </Tabs>
          </div>
        }
        bottomChildren={
          <BottomBar
            tab={activeTab!}
            onSaveSuccess={onReloadFile}
            onDiscardDraft={handleDiscardDraft}
            readOnly={readOnly}
            selectedElementId={selectedElementId}
            elements={elements}
            componentIndex={componentIndex}
          />
        }
      >
        {/* Tabs wrap canvas + bottom code */}
        <Tabs value={activeTabId} onValueChange={onTabChange} className="h-full flex flex-col">
          {/* Tab bar at top */}
          <div className="flex items-center justify-between border-b border-ed-border bg-ed-muted/30">
            <TabsList variant="simple" className="border-0 gap-0 h-auto">
              {tabs.map((tab) => (
                <div key={tab.id} className="group relative flex items-center border-r border-ed-border">
                  <TabsTrigger value={tab.id} className="px-4 py-2.5 text-sm pr-8 rounded-none">
                    {tab.name}
                    {tab.type === 'file' && tab.hasUnsavedChanges && (
                      <Badge variant="warning" className="ml-2 text-[10px]">Draft</Badge>
                    )}
                    {readOnly && (
                      <span className="ml-2 px-1.5 py-0.5 text-[10px] font-medium bg-ed-muted text-ed-muted-foreground rounded">
                        read only
                      </span>
                    )}
                  </TabsTrigger>
                  {tabs.length > 1 && (
                    <span
                      onClick={() => onTabClose(tab.id)}
                      className="absolute right-2 opacity-0 group-hover:opacity-100 hover:bg-ed-accent rounded p-1 cursor-pointer transition-opacity"
                    >
                      <X size={14} weight="bold" className="text-ed-muted-foreground" />
                    </span>
                  )}
                </div>
              ))}
            </TabsList>
            {selectedElementId && (
              <div className="px-3 shrink-0">
                <Button
                  variant="default"
                  size="sm"
                  onClick={handleShareLink}
                  className="gap-1.5"
                  LeftIcon={LinkIcon}
                >
                  Share
                </Button>
              </div>
            )}
          </div>

          {/* Each tab's canvas */}
          {tabs.map((tab) => (
            <TabsContent key={tab.id} value={tab.id} className="flex-1 m-0">
              <DndContext
                id={`dnd-${tab.id}`}
                sensors={readOnly ? [] : sensors}
                onDragStart={readOnly ? undefined : handleDragStart}
                onDragMove={readOnly ? undefined : handleDragMove}
                onDragEnd={readOnly ? undefined : handleDragEnd}
                onDragCancel={readOnly ? undefined : handleDragCancel}
              >
                <Canvas
                  elements={tab.elements}
                  selectedElementIds={selectedElementIds}
                  hoverElementId={hoverElementId}
                  onSelectElement={handleSelectElement}
                  onHoverElement={(id: string | null) => setHoverElementId(id)}
                  onDoubleClickDrillIn={onDoubleClickDrillIn}
                  onResizeElement={onResizeElement}
                  onEditText={onEditText}
                  editingTextId={editingTextId}
                  editingTextBounds={editingTextBounds}
                  onStartEditText={(id, bounds) => {
                    setEditingTextId(id);
                    setEditingTextBounds(bounds);
                  }}
                  onStopEditText={() => {
                    setEditingTextId(null);
                    setEditingTextBounds(null);
                  }}
                  isDragging={isDragging}
                  draggedIds={draggedIds}
                  potentialParentId={overId}
                  components={{
                    ...components,
                    ...snapshots
                  }}
                  componentIndex={componentIndex}
                  iconLibraries={iconLibraries}
                  onZoomChange={setCanvasZoom}
                  onTransformChange={(t) => {
                    canvasTransformRef.current = t
                    // Skip saving until we've loaded from localStorage (prevents overwriting saved values on mount)
                    if (!hasLoadedTransformRef.current) return
                    // Save transform to the current tab
                    setTabs(prev => prev.map(prevTab =>
                      prevTab.id === tab.id ? { ...prevTab, transform: t } : prevTab
                    ))
                    // Also save to localStorage for persistence across sessions
                    if (typeof window !== 'undefined' && tab.type === 'canvas') {
                      localStorage.setItem('lunagraph-canvas-transform', JSON.stringify(t))
                    }
                  }}
                  canvasRefProp={canvasRef}
                  viewportRefProp={viewportRef}
                  cmdPressed={cmdPressed}
                  snapshotContent={tab.type === 'file' && tab.id === activeTabId ? snapshotRendererElement : null}
                  onAddElement={onAddElement}
                  readOnly={readOnly}
                  initialTransform={(tab.type === 'canvas' ? initialCanvasTransform : undefined) || tab.transform}
                  onUpdateElementStyles={onUpdateElementStyles}
                  onUpdateElementProps={onUpdateElementProps}
                  key={`canvas-${tab.id}-${transformKey}`}
                />
                <DragOverlay dropAnimation={null}>
                  {activeElements.length > 0 && activeElement && (
                    <div style={{ transform: `scale(${canvasZoom})`, transformOrigin: 'top left' }}>
                      {activeElements.length === 1 ? (
                        // Single element drag - render normally
                        renderElement(activeElements[0], {
                          isDragPreview: true,
                          components,
                          componentIndex,
                          iconLibraries,
                          devServerUrl,
                        })
                      ) : (
                        // Multi-element drag - render all with relative positioning
                        // Position relative to the actively dragged element (activeElement)
                        <div style={{ position: 'relative' }}>
                          {activeElements.map((el) => {
                            // Position elements relative to the actively dragged element
                            const activePos = activeElement.canvasPosition || { x: 0, y: 0 };
                            const thisPos = el.canvasPosition || { x: 0, y: 0 };
                            const offsetX = thisPos.x - activePos.x;
                            const offsetY = thisPos.y - activePos.y;
                            const isActive = el.id === activeId;

                            return (
                              <div
                                key={el.id}
                                style={{
                                  position: isActive ? 'relative' : 'absolute',
                                  left: isActive ? 0 : offsetX,
                                  top: isActive ? 0 : offsetY,
                                }}
                              >
                                {renderElement(el, {
                                  isDragPreview: true,
                                  components,
                                  componentIndex,
                                  iconLibraries,
                                  devServerUrl,
                                })}
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  )}
                </DragOverlay>

              </DndContext>
            </TabsContent>
          ))}
        </Tabs>

        {/* Create Component Modal */}
        <CreateComponentModal
          isOpen={showCreateComponentModal}
          onClose={() => setShowCreateComponentModal(false)}
          onConfirm={onCreateComponent}
        />

        {/* Draft Conflict Dialog */}
        {draftConflict && (
          <DraftConflictDialog
            isOpen={draftConflict.isOpen}
            componentName={draftConflict.componentName}
            onLoadFromCode={onDraftConflictLoadFromCode}
            onContinueWithDraft={onDraftConflictContinueWithDraft}
          />
        )}
      </CanvasLayout>

    </>
  )
}

// Main export - wraps with DevServerProvider
export const LunagraphEditor = ({
  devServerUrl,
  ...props
}: LunagraphEditorProps) => {
  return (
    <DevServerProvider url={devServerUrl}>
      <LunagraphEditorInner {...props} />
    </DevServerProvider>
  )
}
